package ai

import (
	"sync/atomic"
	"testing"
	"time"

	"github.com/Vadman97/GolangChessAI/pkg/chessai/color"
	"github.com/Vadman97/GolangChessAI/pkg/chessai/location"
)

func TestABDADAFreshRootBatchMatchesIsolatedSearches(t *testing.T) {
	b := boardFromFENPlacement(t, "4qk2/1Q4pp/8/p1P5/1nB5/6P1/1PbN1P1P/2K4R")
	before := b.Hash()
	ab := &ABDADA{NumThreads: 4}
	ab.player = NewAIPlayer(color.Black, ab)
	ab.player.TranspositionTableEnabled = true
	moves := make([]location.Move, 0, 4)
	wanted := map[string]bool{"g7g5": true, "e8g6": true, "e8e7": true, "e8h5": true}
	for _, move := range *b.GetAllMoves(color.Black, nil) {
		if wanted[move.UCIString()] {
			moves = append(moves, move)
		}
	}
	if len(moves) != len(wanted) {
		t.Fatal("missing legal verification candidates")
	}
	want := make(map[string]ScoredMove, len(moves))
	for _, move := range moves {
		want[move.UCIString()] = ab.searchRootMoveFresh(b, move, 5)
	}
	for _, reversed := range []bool{false, true} {
		if reversed {
			for i, j := 0, len(moves)-1; i < j; i, j = i+1, j-1 {
				moves[i], moves[j] = moves[j], moves[i]
			}
		}
		got := ab.searchRootMovesFresh(b, moves, 5)
		if len(got) != len(moves) {
			t.Fatalf("got %d results for %d candidates", len(got), len(moves))
		}
		for i, move := range moves {
			ref := want[move.UCIString()]
			if !sameRootMove(got[i], ref) || got[i].Score != ref.Score || got[i].PathDependentDraw != ref.PathDependentDraw {
				t.Fatalf("candidate %s: parallel=%+v isolated=%+v", move.UCIString(), got[i], ref)
			}
		}
	}
	if b.Hash() != before {
		t.Fatal("verification changed the live board")
	}
}

func TestABDADAFreshRootBatchHonorsOwnerAbort(t *testing.T) {
	b := boardFromFENPlacement(t, "4qk2/1Q4pp/8/p1P5/1nB5/6P1/1PbN1P1P/2K4R")
	ab := &ABDADA{NumThreads: 4}
	ab.player = NewAIPlayer(color.Black, ab)
	ab.player.TranspositionTableEnabled = true
	done := make(chan struct{})
	go func() {
		ab.searchRootMovesFresh(b, *b.GetAllMoves(color.Black, nil), 12)
		close(done)
	}()
	deadline := time.After(5 * time.Second)
	for atomic.LoadUint64(&ab.player.Metrics.MovesConsidered) == 0 {
		select {
		case <-deadline:
			ab.player.Abort()
			t.Fatal("verification did not start")
		default:
			time.Sleep(time.Millisecond)
		}
	}
	ab.player.Abort()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("verification did not join aborted workers")
	}
	if !ab.player.isAborted() {
		t.Fatal("verification cleared owner cancellation")
	}
}

